UPDATE TB_EEP_HR_INTV_M SET
	  APLY_NM = #{APLY_NM}, GENDER = #{GENDER}, INTV_DT = NULLIF(#{INTV_DT}, ''), INTV_TM = #{INTV_TM}
	, APLY_TARGET = #{APLY_TARGET}, APLY_ROUTE = #{APLY_ROUTE}, PHONE = #{PHONE}, ATTEND_ST = #{ATTEND_ST}
	, EDU = #{EDU}, AGE = #{AGE}, ADDR = #{ADDR}, STATION = #{STATION}, CAREER = #{CAREER}, LANG = #{LANG}
	, LOCAL_YN = #{LOCAL_YN}, HOBBY = #{HOBBY}, SPECIALTY = #{SPECIALTY}, SALARY = #{SALARY}
	, RESULT_ST = #{RESULT_ST}, NOTICE_ST = #{NOTICE_ST}, JOIN_ST = #{JOIN_ST}, JOIN_DT = #{JOIN_DT}
	, REFERRER = #{REFERRER}, LANG_NOTE = #{LANG_NOTE}
	, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE INTV_SQ = #{INTV_SQ}

UPDATE TB_EEP_HR_TRAINEE_M SET
	  STATUS_CD = #{STATUS_CD}, LEAVE_NOTE = #{LEAVE_NOTE}, TRN_NM = #{TRN_NM}, GENDER = #{GENDER}, EDU = #{EDU}, AGE = #{AGE}
	, ADDR = #{ADDR}, STATION = #{STATION}, CAREER = #{CAREER}, LANG = #{LANG}, LANG_NOTE = #{LANG_NOTE}, LOCAL_YN = #{LOCAL_YN}
	, EARLY_YN = #{EARLY_YN}, SPECIAL_YN = #{SPECIAL_YN}, EDU_START_DT = NULLIF(#{EDU_START_DT}, '')
	, INTERVIEW_YN = #{INTERVIEW_YN}, INTERVIEW_AVAIL = #{INTERVIEW_AVAIL}
	, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE TRN_SQ = #{TRN_SQ}

UPDATE TB_EEP_HR_TRAINEE_M SET
	  ${FIELD} = NULLIF(#{VALUE}, ''), UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE TRN_SQ = #{TRN_SQ}

UPDATE TB_EEP_HR_INTV_M SET
	  ${FIELD} = NULLIF(#{VALUE}, ''), UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE INTV_SQ = #{INTV_SQ}

UPDATE TB_EEP_HR_TRAINEE_M SET
	  ${SKILL_COL} = NULLIF(#{SKILL_VAL}, ''), UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE TRN_SQ = #{TRN_SQ}
